// Generates the bridge's interop vectors from the Eggomi keeper's own code.
// Usage: node gen-interop.mjs <eggomi checkout> > testdata/interop.json
import { createHash } from "node:crypto";
import path from "node:path";
import { pathToFileURL } from "node:url";

const repo = process.argv[2];
const imp = (p) => import(pathToFileURL(path.join(repo, p)).href);
const { KkInitiator, KkResponder, publicKeyOf } = await imp("packages/host-runtime/src/noise.mjs");
const { CHANNEL_PROLOGUE, encodeFrame } = await imp("infra/dstack/keeper/cah.mjs");
const { seal, BOUND_FIELDS } = await imp("infra/dstack/keeper/seal.mjs");

const key = (label) => createHash("sha256").update(label).digest();
const hex = (b) => Buffer.from(b).toString("hex");
const EMPTY = Buffer.alloc(0);

const keeperStatic = key("eggomi-meta-bridge test keeper static");
const bridgeStatic = key("eggomi-meta-bridge test bridge static");
const keeperEph = key("eggomi-meta-bridge test keeper ephemeral");
const bridgeEph = key("eggomi-meta-bridge test bridge ephemeral");
const guardStatic = key("eggomi-meta-bridge test guard static");

const init = new KkInitiator({
  prologue: CHANNEL_PROLOGUE,
  staticPrivateKey: keeperStatic,
  remoteStatic: publicKeyOf(bridgeStatic),
  ephemeral: keeperEph,
});
const resp = new KkResponder({
  prologue: CHANNEL_PROLOGUE,
  staticPrivateKey: bridgeStatic,
  remoteStatic: publicKeyOf(keeperStatic),
  ephemeral: bridgeEph,
});
const msg1 = init.writeMessage1();
resp.readMessage1(msg1);
const w2 = resp.writeMessage2();
const t1 = init.readMessage2(w2.message).transport;
const t2 = w2.transport;
const request = '{"id":1,"method":"health","params":{}}';
const replyText = '{"id":1,"result":{"ok":true}}';
const reqCt = t1.send.encryptWithAd(EMPTY, Buffer.from(request));
const repCt = t2.send.encryptWithAd(EMPTY, Buffer.from(replyText));

const bound = {
  grant_ref: hex(key("grant")),
  nonce: hex(key("nonce")).slice(0, 32),
  tenant: "tenant-test",
  audience: hex(publicKeyOf(keeperStatic)),
  recipient_instance: "meta-bridge",
  recipient_generation: 1,
  origin: "https://www.facebook.com",
  field: "cookies",
  frame_id: "frame-test",
  navigation_generation: 1,
  lease_fence: 1,
  keeper_epoch: 1,
  challenge: hex(key("challenge")).slice(0, 32),
  requester: "owner",
  task: "messenger.connect",
  operation: "messenger.connect",
  resource: "meta-bridge",
};
const canaryCookies = {
  datr: "CANARY-DATR-VALUE",
  c_user: "100000000000001",
  sb: "CANARY-SB-VALUE",
  xs: "CANARY-XS-VALUE",
};
const sealTo = (b, secret) =>
  seal({ keeperPrivate: guardStatic, guardPublic: publicKeyOf(bridgeStatic), bound: b, secret });
const sealed = sealTo(bound, JSON.stringify(canaryCookies));
const variant = (label, overrides, secret = canaryCookies) =>
  sealTo({ ...bound, grant_ref: hex(key("grant " + label)), ...overrides }, JSON.stringify(secret));
const { xs: _xs, ...withoutXs } = canaryCookies;
const variants = {
  fresh: [1, 2, 3, 4].map((i) => variant("fresh " + i, {})),
  otherInstance: variant("instance", { recipient_instance: "browser-guard-1" }),
  otherGeneration: variant("generation", { recipient_generation: 2 }),
  otherOrigin: variant("origin", { origin: "https://www.messenger.com" }),
  otherField: variant("field", { field: "password" }),
  otherAudience: variant("audience", { audience: hex(publicKeyOf(guardStatic)) }),
  extraCookie: variant("extra", {}, { ...canaryCookies, presence: "CANARY-EXTRA-VALUE" }),
  missingXs: variant("missing", {}, withoutXs),
};

process.stdout.write(
  JSON.stringify(
    {
      note: "Generated by testdata/gen-interop.mjs from the Eggomi keeper's noise.mjs, cah.mjs and seal.mjs. Test keys and canary values only.",
      boundFields: BOUND_FIELDS,
      kk: {
        prologue: CHANNEL_PROLOGUE.toString("utf8"),
        keeperStatic: hex(keeperStatic),
        keeperPublic: hex(publicKeyOf(keeperStatic)),
        bridgeStatic: hex(bridgeStatic),
        bridgePublic: hex(publicKeyOf(bridgeStatic)),
        keeperEphemeral: hex(keeperEph),
        bridgeEphemeral: hex(bridgeEph),
        helloFrame: hex(encodeFrame(Buffer.concat([Buffer.of(1), msg1]))),
        message2: hex(w2.message),
        request,
        requestCiphertext: hex(reqCt),
        reply: replyText,
        replyCiphertext: hex(repCt),
        handshakeHash: hex(t2.handshakeHash),
      },
      seal: {
        sealerStatic: hex(guardStatic),
        sealerPublic: hex(publicKeyOf(guardStatic)),
        recipientStatic: hex(bridgeStatic),
        recipientPublic: hex(publicKeyOf(bridgeStatic)),
        blob: sealed,
        plaintext: canaryCookies,
        variants,
      },
    },
    null,
    2,
  ) + "\n",
);
